head.script:
/*
 * [이슈] input onEditKeyUp 이벤트 시 oldValue / newValue 오류
 * 증상: 숫자를 빠르게 연속으로 입력할 경우, oldValue 와 newValue 모두
 *      마지막으로 입력된 값만 표시되는 현상이 발생.
 *
 * 재현 절차
 *  1) 아래 input 에 숫자를 빠르게 연타 입력 (예: 12345)
 *  2) output textarea 의 로그에서 oldValue / newValue 비교
 *     정상: oldValue 는 직전 값, newValue 는 현재 값 이어야 함
 *     버그: 두 값이 마지막으로 입력된 값으로 동일하게 표시됨
 */

scwin.onpageload = function() {
    output1.setValue("");
};

scwin.input1_oneditkeyup = function(info, e) {
    var logStr = "[" + new Date().toLocaleTimeString() + "] "
               + "keyCode=" + info.keyCode
               + ", oldValue=\"" + info.oldValue + "\""
               + ", newValue=\"" + info.newValue + "\"";
    console.log(logStr);
    var prev = output1.getValue() || "";
    output1.setValue(prev + logStr + "\n");
};

scwin.trigger_clear_onclick = function() {
    input1.setValue("");
    output1.setValue("");
};
